        impl < K , V , S > IndexMap < K , V , S > where K : Hash + Eq , S : BuildHasher , { # [doc = " Insert a key-value pair in the map."] # [doc = ""] # [doc = " If an equivalent key already exists in the map: the key remains and"] # [doc = " retains in its place in the order, its corresponding value is updated"] # [doc = " with `value`, and the older value is returned inside `Some(_)`."] # [doc = ""] # [doc = " If no equivalent key existed in the map: the new key-value pair is"] # [doc = " inserted, last in order, and `None` is returned."] # [doc = ""] # [doc = " Computes in **O(1)** time (amortized average)."] # [doc = ""] # [doc = " See also [`entry`][Self::entry] if you want to insert *or* modify,"] # [doc = " or [`insert_full`][Self::insert_full] if you need to get the index of"] # [doc = " the corresponding key-value pair."] pub fn insert (& mut self , key : K , value : V) -> Option < V > { self . insert_full (key , value) . 1 } # [doc = " Insert a key-value pair in the map, and get their index."] # [doc = ""] # [doc = " If an equivalent key already exists in the map: the key remains and"] # [doc = " retains in its place in the order, its corresponding value is updated"] # [doc = " with `value`, and the older value is returned inside `(index, Some(_))`."] # [doc = ""] # [doc = " If no equivalent key existed in the map: the new key-value pair is"] # [doc = " inserted, last in order, and `(index, None)` is returned."] # [doc = ""] # [doc = " Computes in **O(1)** time (amortized average)."] # [doc = ""] # [doc = " See also [`entry`][Self::entry] if you want to insert *or* modify."] pub fn insert_full (& mut self , key : K , value : V) -> (usize , Option < V >) { let hash = self . hash (& key) ; self . core . insert_full (hash , key , value) } # [doc = " Insert a key-value pair in the map at its ordered position among sorted keys."] # [doc = ""] # [doc = " This is equivalent to finding the position with"] # [doc = " [`binary_search_keys`][Self::binary_search_keys], then either updating"] # [doc = " it or calling [`insert_before`][Self::insert_before] for a new key."] # [doc = ""] # [doc = " If the sorted key is found in the map, its corresponding value is"] # [doc = " updated with `value`, and the older value is returned inside"] # [doc = " `(index, Some(_))`. Otherwise, the new key-value pair is inserted at"] # [doc = " the sorted position, and `(index, None)` is returned."] # [doc = ""] # [doc = " If the existing keys are **not** already sorted, then the insertion"] # [doc = " index is unspecified (like [`slice::binary_search`]), but the key-value"] # [doc = " pair is moved to or inserted at that position regardless."] # [doc = ""] # [doc = " Computes in **O(n)** time (average). Instead of repeating calls to"] # [doc = " `insert_sorted`, it may be faster to call batched [`insert`][Self::insert]"] # [doc = " or [`extend`][Self::extend] and only call [`sort_keys`][Self::sort_keys]"] # [doc = " or [`sort_unstable_keys`][Self::sort_unstable_keys] once."] pub fn insert_sorted (& mut self , key : K , value : V) -> (usize , Option < V >) where K : Ord , { match self . binary_search_keys (& key) { Ok (i) => (i , Some (mem :: replace (& mut self [i] , value))) , Err (i) => self . insert_before (i , key , value) , } } # [doc = " Insert a key-value pair in the map at its ordered position among keys"] # [doc = " sorted by `cmp`."] # [doc = ""] # [doc = " This is equivalent to finding the position with"] # [doc = " [`binary_search_by`][Self::binary_search_by], then calling"] # [doc = " [`insert_before`][Self::insert_before] with the given key and value."] # [doc = ""] # [doc = " If the existing keys are **not** already sorted, then the insertion"] # [doc = " index is unspecified (like [`slice::binary_search`]), but the key-value"] # [doc = " pair is moved to or inserted at that position regardless."] # [doc = ""] # [doc = " Computes in **O(n)** time (average)."] pub fn insert_sorted_by < F > (& mut self , key : K , value : V , mut cmp : F) -> (usize , Option < V >) where F : FnMut (& K , & V , & K , & V) -> Ordering , { let (Ok (i) | Err (i)) = self . binary_search_by (| k , v | cmp (k , v , & key , & value)) ; self . insert_before (i , key , value) } # [doc = " Insert a key-value pair in the map at its ordered position"] # [doc = " using a sort-key extraction function."] # [doc = ""] # [doc = " This is equivalent to finding the position with"] # [doc = " [`binary_search_by_key`][Self::binary_search_by_key] with `sort_key(key)`, then"] # [doc = " calling [`insert_before`][Self::insert_before] with the given key and value."] # [doc = ""] # [doc = " If the existing keys are **not** already sorted, then the insertion"] # [doc = " index is unspecified (like [`slice::binary_search`]), but the key-value"] # [doc = " pair is moved to or inserted at that position regardless."] # [doc = ""] # [doc = " Computes in **O(n)** time (average)."] pub fn insert_sorted_by_key < B , F > (& mut self , key : K , value : V , mut sort_key : F ,) -> (usize , Option < V >) where B : Ord , F : FnMut (& K , & V) -> B , { let search_key = sort_key (& key , & value) ; let (Ok (i) | Err (i)) = self . binary_search_by_key (& search_key , sort_key) ; self . insert_before (i , key , value) } # [doc = " Insert a key-value pair in the map before the entry at the given index, or at the end."] # [doc = ""] # [doc = " If an equivalent key already exists in the map: the key remains and"] # [doc = " is moved to the new position in the map, its corresponding value is updated"] # [doc = " with `value`, and the older value is returned inside `Some(_)`. The returned index"] # [doc = " will either be the given index or one less, depending on how the entry moved."] # [doc = " (See [`shift_insert`](Self::shift_insert) for different behavior here.)"] # [doc = ""] # [doc = " If no equivalent key existed in the map: the new key-value pair is"] # [doc = " inserted exactly at the given index, and `None` is returned."] # [doc = ""] # [doc = " ***Panics*** if `index` is out of bounds."] # [doc = " Valid indices are `0..=map.len()` (inclusive)."] # [doc = ""] # [doc = " Computes in **O(n)** time (average)."] # [doc = ""] # [doc = " See also [`entry`][Self::entry] if you want to insert *or* modify,"] # [doc = " perhaps only using the index for new entries with [`VacantEntry::shift_insert`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use indexmap::IndexMap;"] # [doc = " let mut map: IndexMap<char, ()> = ('a'..='z').map(|c| (c, ())).collect();"] # [doc = ""] # [doc = " // The new key '*' goes exactly at the given index."] # [doc = " assert_eq!(map.get_index_of(&'*'), None);"] # [doc = " assert_eq!(map.insert_before(10, '*', ()), (10, None));"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(10));"] # [doc = ""] # [doc = " // Moving the key 'a' up will shift others down, so this moves *before* 10 to index 9."] # [doc = " assert_eq!(map.insert_before(10, 'a', ()), (9, Some(())));"] # [doc = " assert_eq!(map.get_index_of(&'a'), Some(9));"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(10));"] # [doc = ""] # [doc = " // Moving the key 'z' down will shift others up, so this moves to exactly 10."] # [doc = " assert_eq!(map.insert_before(10, 'z', ()), (10, Some(())));"] # [doc = " assert_eq!(map.get_index_of(&'z'), Some(10));"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(11));"] # [doc = ""] # [doc = " // Moving or inserting before the endpoint is also valid."] # [doc = " assert_eq!(map.len(), 27);"] # [doc = " assert_eq!(map.insert_before(map.len(), '*', ()), (26, Some(())));"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(26));"] # [doc = " assert_eq!(map.insert_before(map.len(), '+', ()), (27, None));"] # [doc = " assert_eq!(map.get_index_of(&'+'), Some(27));"] # [doc = " assert_eq!(map.len(), 28);"] # [doc = " ```"] # [track_caller] pub fn insert_before (& mut self , mut index : usize , key : K , value : V) -> (usize , Option < V >) { let len = self . len () ; assert ! (index <= len , "index out of bounds: the len is {len} but the index is {index}. Expected index <= len") ; match self . entry (key) { Entry :: Occupied (mut entry) => { if index > entry . index () { index -= 1 ; } let old = mem :: replace (entry . get_mut () , value) ; entry . move_index (index) ; (index , Some (old)) } Entry :: Vacant (entry) => { entry . shift_insert (index , value) ; (index , None) } } } # [doc = " Insert a key-value pair in the map at the given index."] # [doc = ""] # [doc = " If an equivalent key already exists in the map: the key remains and"] # [doc = " is moved to the given index in the map, its corresponding value is updated"] # [doc = " with `value`, and the older value is returned inside `Some(_)`."] # [doc = " Note that existing entries **cannot** be moved to `index == map.len()`!"] # [doc = " (See [`insert_before`](Self::insert_before) for different behavior here.)"] # [doc = ""] # [doc = " If no equivalent key existed in the map: the new key-value pair is"] # [doc = " inserted at the given index, and `None` is returned."] # [doc = ""] # [doc = " ***Panics*** if `index` is out of bounds."] # [doc = " Valid indices are `0..map.len()` (exclusive) when moving an existing entry, or"] # [doc = " `0..=map.len()` (inclusive) when inserting a new key."] # [doc = ""] # [doc = " Computes in **O(n)** time (average)."] # [doc = ""] # [doc = " See also [`entry`][Self::entry] if you want to insert *or* modify,"] # [doc = " perhaps only using the index for new entries with [`VacantEntry::shift_insert`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use indexmap::IndexMap;"] # [doc = " let mut map: IndexMap<char, ()> = ('a'..='z').map(|c| (c, ())).collect();"] # [doc = ""] # [doc = " // The new key '*' goes exactly at the given index."] # [doc = " assert_eq!(map.get_index_of(&'*'), None);"] # [doc = " assert_eq!(map.shift_insert(10, '*', ()), None);"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(10));"] # [doc = ""] # [doc = " // Moving the key 'a' up to 10 will shift others down, including the '*' that was at 10."] # [doc = " assert_eq!(map.shift_insert(10, 'a', ()), Some(()));"] # [doc = " assert_eq!(map.get_index_of(&'a'), Some(10));"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(9));"] # [doc = ""] # [doc = " // Moving the key 'z' down to 9 will shift others up, including the '*' that was at 9."] # [doc = " assert_eq!(map.shift_insert(9, 'z', ()), Some(()));"] # [doc = " assert_eq!(map.get_index_of(&'z'), Some(9));"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(10));"] # [doc = ""] # [doc = " // Existing keys can move to len-1 at most, but new keys can insert at the endpoint."] # [doc = " assert_eq!(map.len(), 27);"] # [doc = " assert_eq!(map.shift_insert(map.len() - 1, '*', ()), Some(()));"] # [doc = " assert_eq!(map.get_index_of(&'*'), Some(26));"] # [doc = " assert_eq!(map.shift_insert(map.len(), '+', ()), None);"] # [doc = " assert_eq!(map.get_index_of(&'+'), Some(27));"] # [doc = " assert_eq!(map.len(), 28);"] # [doc = " ```"] # [doc = ""] # [doc = " ```should_panic"] # [doc = " use indexmap::IndexMap;"] # [doc = " let mut map: IndexMap<char, ()> = ('a'..='z').map(|c| (c, ())).collect();"] # [doc = ""] # [doc = " // This is an invalid index for moving an existing key!"] # [doc = " map.shift_insert(map.len(), 'a', ());"] # [doc = " ```"] # [track_caller] pub fn shift_insert (& mut self , index : usize , key : K , value : V) -> Option < V > { let len = self . len () ; match self . entry (key) { Entry :: Occupied (mut entry) => { assert ! (index < len , "index out of bounds: the len is {len} but the index is {index}") ; let old = mem :: replace (entry . get_mut () , value) ; entry . move_index (index) ; Some (old) } Entry :: Vacant (entry) => { assert ! (index <= len , "index out of bounds: the len is {len} but the index is {index}. Expected index <= len") ; entry . shift_insert (index , value) ; None } } } # [doc = " Replaces the key at the given index. The new key does not need to be"] # [doc = " equivalent to the one it is replacing, but it must be unique to the rest"] # [doc = " of the map."] # [doc = ""] # [doc = " Returns `Ok(old_key)` if successful, or `Err((other_index, key))` if an"] # [doc = " equivalent key already exists at a different index. The map will be"] # [doc = " unchanged in the error case."] # [doc = ""] # [doc = " Direct indexing can be used to change the corresponding value: simply"] # [doc = " `map[index] = value`, or `mem::replace(&mut map[index], value)` to"] # [doc = " retrieve the old value as well."] # [doc = ""] # [doc = " ***Panics*** if `index` is out of bounds."] # [doc = ""] # [doc = " Computes in **O(1)** time (average)."] # [track_caller] pub fn replace_index (& mut self , index : usize , key : K) -> Result < K , (usize , K) > { let entry = & mut self . as_entries_mut () [index] ; if key == entry . key { return Ok (mem :: replace (& mut entry . key , key)) ; } let hash = self . hash (& key) ; if let Some (i) = self . core . get_index_of (hash , & key) { debug_assert_ne ! (i , index) ; return Err ((i , key)) ; } Ok (self . core . replace_index_unique (index , hash , key)) } # [doc = " Get the given key's corresponding entry in the map for insertion and/or"] # [doc = " in-place manipulation."] # [doc = ""] # [doc = " Computes in **O(1)** time (amortized average)."] pub fn entry (& mut self , key : K) -> Entry < '_ , K , V > { let hash = self . hash (& key) ; self . core . entry (hash , key) } # [doc = " Creates a splicing iterator that replaces the specified range in the map"] # [doc = " with the given `replace_with` key-value iterator and yields the removed"] # [doc = " items. `replace_with` does not need to be the same length as `range`."] # [doc = ""] # [doc = " The `range` is removed even if the iterator is not consumed until the"] # [doc = " end. It is unspecified how many elements are removed from the map if the"] # [doc = " `Splice` value is leaked."] # [doc = ""] # [doc = " The input iterator `replace_with` is only consumed when the `Splice`"] # [doc = " value is dropped. If a key from the iterator matches an existing entry"] # [doc = " in the map (outside of `range`), then the value will be updated in that"] # [doc = " position. Otherwise, the new key-value pair will be inserted in the"] # [doc = " replaced `range`."] # [doc = ""] # [doc = " ***Panics*** if the starting point is greater than the end point or if"] # [doc = " the end point is greater than the length of the map."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use indexmap::IndexMap;"] # [doc = ""] # [doc = " let mut map = IndexMap::from([(0, '_'), (1, 'a'), (2, 'b'), (3, 'c'), (4, 'd')]);"] # [doc = " let new = [(5, 'E'), (4, 'D'), (3, 'C'), (2, 'B'), (1, 'A')];"] # [doc = " let removed: Vec<_> = map.splice(2..4, new).collect();"] # [doc = ""] # [doc = " // 1 and 4 got new values, while 5, 3, and 2 were newly inserted."] # [doc = " assert!(map.into_iter().eq([(0, '_'), (1, 'A'), (5, 'E'), (3, 'C'), (2, 'B'), (4, 'D')]));"] # [doc = " assert_eq!(removed, &[(2, 'b'), (3, 'c')]);"] # [doc = " ```"] # [track_caller] pub fn splice < R , I > (& mut self , range : R , replace_with : I) -> Splice < '_ , I :: IntoIter , K , V , S > where R : RangeBounds < usize > , I : IntoIterator < Item = (K , V) > , { Splice :: new (self , range , replace_with . into_iter ()) } # [doc = " Moves all key-value pairs from `other` into `self`, leaving `other` empty."] # [doc = ""] # [doc = " This is equivalent to calling [`insert`][Self::insert] for each"] # [doc = " key-value pair from `other` in order, which means that for keys that"] # [doc = " already exist in `self`, their value is updated in the current position."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use indexmap::IndexMap;"] # [doc = ""] # [doc = " // Note: Key (3) is present in both maps."] # [doc = " let mut a = IndexMap::from([(3, \"c\"), (2, \"b\"), (1, \"a\")]);"] # [doc = " let mut b = IndexMap::from([(3, \"d\"), (4, \"e\"), (5, \"f\")]);"] # [doc = " let old_capacity = b.capacity();"] # [doc = ""] # [doc = " a.append(&mut b);"] # [doc = ""] # [doc = " assert_eq!(a.len(), 5);"] # [doc = " assert_eq!(b.len(), 0);"] # [doc = " assert_eq!(b.capacity(), old_capacity);"] # [doc = ""] # [doc = " assert!(a.keys().eq(&[3, 2, 1, 4, 5]));"] # [doc = " assert_eq!(a[&3], \"d\"); // \"c\" was overwritten."] # [doc = " ```"] pub fn append < S2 > (& mut self , other : & mut IndexMap < K , V , S2 >) { self . extend (other . drain (..)) ; } }
